import{_ as c,c as r,o as i,j as e,a8 as t,t as s,a as n}from"./chunks/framework.jsZJWZJf.js";const q=JSON.parse('{"title":"被讨厌的勇气：“自我启发之父”阿德勒的哲学课 - 读书笔记","description":"","frontmatter":{"title":"被讨厌的勇气：“自我启发之父”阿德勒的哲学课 - 读书笔记","outline":[2,2],"finishedDate":"2025-08-07"},"headers":[],"relativePath":"blog/read/books/被讨厌的勇气.md","filePath":"blog/read/books/被讨厌的勇气.md","lastUpdated":1795017144000}'),b={name:"blog/read/books/被讨厌的勇气.md"},l={class:"social-psychology-notes"},p={class:"reading-book","aria-label":"书籍信息"},v={class:"reading-book-info"},o={class:"reading-metadata"},f=["datetime"];function u(d,a,g,x,k,h){return i(),r("div",null,[e("div",l,[a[8]||(a[8]=e("header",{class:"reading-header"},[e("h1",null,"被讨厌的勇气：“自我启发之父”阿德勒的哲学课"),e("p",{class:"reading-byline"},"作者：岸见一郎 古贺史健"),e("div",{class:"reading-stats"},[e("span",null,"21 条摘抄"),e("span",null,"1 则随想"),e("span",null,"微信读书")])],-1)),e("section",p,[a[7]||(a[7]=e("div",{class:"reading-cover"},[e("img",{src:"https://wfqqreader-1252317822.image.myqcloud.com/cover/385/25615385/t6_25615385.jpg",alt:"被讨厌的勇气：“自我启发之父”阿德勒的哲学课封面",width:"160",loading:"lazy"})],-1)),e("div",v,[a[4]||(a[4]=e("p",{class:"reading-book-title"},"书籍信息",-1)),e("dl",o,[a[1]||(a[1]=t("<div data-v-e5ecfb2d><dt data-v-e5ecfb2d>书名</dt><dd data-v-e5ecfb2d>被讨厌的勇气：“自我启发之父”阿德勒的哲学课</dd></div><div data-v-e5ecfb2d><dt data-v-e5ecfb2d>作者</dt><dd data-v-e5ecfb2d>岸见一郎 古贺史健</dd></div><div data-v-e5ecfb2d><dt data-v-e5ecfb2d>出版社</dt><dd data-v-e5ecfb2d>机械工业出版社</dd></div><div data-v-e5ecfb2d><dt data-v-e5ecfb2d>出版时间</dt><dd data-v-e5ecfb2d>2017-05-01 00:00:00</dd></div>",4)),e("div",null,[a[0]||(a[0]=e("dt",null,"完读日期",-1)),e("dd",null,[e("time",{datetime:d.$frontmatter.finishedDate},s(d.$frontmatter.finishedDate),9,f)])]),a[2]||(a[2]=e("div",null,[e("dt",null,"ISBN"),e("dd",null,"9787111495482")],-1)),a[3]||(a[3]=e("div",null,[e("dt",null,"分类"),e("dd",null,"心理-积极心理学")],-1))]),a[5]||(a[5]=e("a",{class:"reading-original-link",href:"https://weread.qq.com/web/reader/8b9329607186dc198b9bdab",target:"_blank",rel:"noopener noreferrer"},[n("在微信读书中打开 "),e("span",{"aria-hidden":"true"},"↗")],-1)),a[6]||(a[6]=e("details",{class:"reading-description"},[e("summary",null,"书籍简介"),e("p",null,"一名深陷自卑、无能与不幸福的青年，听到了一名哲人主张的“世界无比单纯，人人都能幸福”便来挑战，两人展开了你来我往的思考和辩论，在一夜一夜过去后，青年开始思考，为什么“所谓的自由，就是被别人讨厌”？问题不在于世界是什么样子，在于你是什么样子。")],-1))])]),a[9]||(a[9]=t('<h2 id="不为人知的心理学-第三巨头" tabindex="-1" data-v-e5ecfb2d>不为人知的心理学“第三巨头” <a class="header-anchor" href="#不为人知的心理学-第三巨头" aria-label="Permalink to “不为人知的心理学“第三巨头””" data-v-e5ecfb2d>​</a></h2><blockquote class="reading-excerpt" id="excerpt-001" data-v-e5ecfb2d><span class="reading-excerpt-number" aria-hidden="true" data-v-e5ecfb2d>001</span><div data-v-e5ecfb2d><p data-v-e5ecfb2d>任何经历本身并不是成功或者失败的原因。我们并非因为自身经历中的刺激——所谓的心理创伤——而痛苦，事实上我们会从经历中发现符合自己目的的因素。决定我们自身的不是过去的经历，而是我们自己赋予经历的意义。”</p></div></blockquote><h2 id="为什么讨厌自己" tabindex="-1" data-v-e5ecfb2d>为什么讨厌自己？ <a class="header-anchor" href="#为什么讨厌自己" aria-label="Permalink to “为什么讨厌自己？”" data-v-e5ecfb2d>​</a></h2><blockquote class="reading-excerpt" id="excerpt-002" data-v-e5ecfb2d><span class="reading-excerpt-number" aria-hidden="true" data-v-e5ecfb2d>002</span><div data-v-e5ecfb2d><p data-v-e5ecfb2d>健全的自卑感不是来自与别人的比较，而是来自与“理想的自己”的比较</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-003" data-v-e5ecfb2d><span class="reading-excerpt-number" aria-hidden="true" data-v-e5ecfb2d>003</span><div data-v-e5ecfb2d><p data-v-e5ecfb2d>如果在一起感到苦闷或者紧张，那即使是恋爱关系也不能称之为爱。当人能够感觉到“与这个人在一起可以无拘无束”的时候，才能够体会到爱。既没有自卑感也不必炫耀优越性，能够保持一种平静而自然的状态。真正的爱应该是这样的。</p></div></blockquote><h2 id="自由就是不再寻求认可" tabindex="-1" data-v-e5ecfb2d>自由就是不再寻求认可？ <a class="header-anchor" href="#自由就是不再寻求认可" aria-label="Permalink to “自由就是不再寻求认可？”" data-v-e5ecfb2d>​</a></h2><blockquote class="reading-excerpt" id="excerpt-004" data-v-e5ecfb2d><span class="reading-excerpt-number" aria-hidden="true" data-v-e5ecfb2d>004</span><div data-v-e5ecfb2d><p data-v-e5ecfb2d>苦恼于与孩子之间的关系的父母往往容易认为：孩子就是我的人生。总之就是把孩子的课题也看成是自己的课题，总是只考虑孩子，而当意识到的时候，他们已经失去了自我。<br data-v-e5ecfb2d>但即使父母再怎么背负孩子的课题，孩子依然是独立的个人，不会完全按照父母的想法去生活。孩子的学习、工作、结婚对象或者哪怕是日常行为举止都不会完全按照父母所想。当然，我也会担心甚至会想要去干涉。但是，刚才我也说过：“别人不是为了满足你的期待而活。”即使是自己的孩子也不是为了满足父母的期待而活。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-005" data-v-e5ecfb2d><span class="reading-excerpt-number" aria-hidden="true" data-v-e5ecfb2d>005</span><div data-v-e5ecfb2d><p data-v-e5ecfb2d>当然，随着我的变化——不是通过我的变化——对方也会发生改变。也许很多情况下对方不得不改变，但那不是目的，而且也可能不会发生。总之，把改变自己当成操纵他人的手段是一种极其错误的想法。</p></div></blockquote><h2 id="个体心理学和整体论" tabindex="-1" data-v-e5ecfb2d>个体心理学和整体论 <a class="header-anchor" href="#个体心理学和整体论" aria-label="Permalink to “个体心理学和整体论”" data-v-e5ecfb2d>​</a></h2><aside class="reading-thought" aria-label="个人随想" data-v-e5ecfb2d><div class="reading-thought-meta" data-v-e5ecfb2d><span data-v-e5ecfb2d>我的随想</span><time datetime="2025-07-25" data-v-e5ecfb2d>2025/07/25</time></div><p data-v-e5ecfb2d>在工作中也是这样，同事都很优秀，感觉在这样的环境中自己很难被看到，或者在工作中被批评，一段时间总是出错，在工作中会有挫败感，这个时候也应该跳出工作这个环境，去思考自己的价值在哪里？离开了工作环境，我的家庭也很需要我，这是价值，我的花草宠物需要我，这也是价值，抛开工作，我依旧可以做自己喜爱的事情，继续去坚持，去朝着自己想要的方向努力，这个时候就不会那么在意自己在工作环境的失落，也会有继续下去的勇气。</p><blockquote class="reading-thought-source" data-v-e5ecfb2d><p class="reading-source-label" data-v-e5ecfb2d>对应原文</p><p data-v-e5ecfb2d>如果了解了世界之大，就会明白自己在学校中所受的苦只不过是“杯中风暴”而已。只要跳出杯子，猛烈的风暴也会变成微风</p></blockquote></aside><blockquote class="reading-excerpt" id="excerpt-006" data-v-e5ecfb2d><span class="reading-excerpt-number" aria-hidden="true" data-v-e5ecfb2d>006</span><div data-v-e5ecfb2d><p data-v-e5ecfb2d>如果是因为你的反对就能崩塌的关系，那么这种关系从一开始就没有必要缔结，由自己主动舍弃也无所谓。活在害怕关系破裂的恐惧之中，那是为他人而活的一种不自由的生活方式。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-007" data-v-e5ecfb2d><span class="reading-excerpt-number" aria-hidden="true" data-v-e5ecfb2d>007</span><div data-v-e5ecfb2d><p data-v-e5ecfb2d>经济地位跟人的价值毫无关系。公司职员和家庭主妇只是劳动场所和任务不同，完全是“虽不同但平等”</p></div></blockquote><h2 id="过多的自我意识-反而会束缚自己" tabindex="-1" data-v-e5ecfb2d>过多的自我意识，反而会束缚自己 <a class="header-anchor" href="#过多的自我意识-反而会束缚自己" aria-label="Permalink to “过多的自我意识，反而会束缚自己”" data-v-e5ecfb2d>​</a></h2><blockquote class="reading-excerpt" id="excerpt-008" data-v-e5ecfb2d><span class="reading-excerpt-number" aria-hidden="true" data-v-e5ecfb2d>008</span><div data-v-e5ecfb2d><p data-v-e5ecfb2d>假如有10个人，其中势必会有1个人无论遇到什么事都会批判你。他讨厌你，你也不喜欢他。而且，10个人中也会有2个人能够成为与你互相接纳一切的好朋友。剩下的7个人则两者都不是。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-009" data-v-e5ecfb2d><span class="reading-excerpt-number" aria-hidden="true" data-v-e5ecfb2d>009</span><div data-v-e5ecfb2d><p data-v-e5ecfb2d>将焦点聚集到微不足道的一个方面并企图以此来评价整个世界。这就是缺乏人生和谐的错误生活方式。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-010" data-v-e5ecfb2d><span class="reading-excerpt-number" aria-hidden="true" data-v-e5ecfb2d>010</span><div data-v-e5ecfb2d><p data-v-e5ecfb2d>任何人都有自己不再是生产者的时候。例如，上了年纪退休之后不得不靠退休金或孩子们的赡养生活；或者虽然年轻但因为受伤或生病而无法劳动。这种时候，只能用“行为标准”来接受自己的人总会受到非常严重的打击</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-011" data-v-e5ecfb2d><span class="reading-excerpt-number" aria-hidden="true" data-v-e5ecfb2d>011</span><div data-v-e5ecfb2d><p data-v-e5ecfb2d>跨出家门的那一瞬间，“旅行”已经开始，朝着目的地出发途中的每一个瞬间都是旅行。当然，即使因为某些事情而没能够到达金字塔，那也并非没有旅行。这就是现实性的人生。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-012" data-v-e5ecfb2d><span class="reading-excerpt-number" aria-hidden="true" data-v-e5ecfb2d>012</span><div data-v-e5ecfb2d><p data-v-e5ecfb2d>潜在性的行为</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-013" data-v-e5ecfb2d><span class="reading-excerpt-number" aria-hidden="true" data-v-e5ecfb2d>013</span><div data-v-e5ecfb2d><p data-v-e5ecfb2d>现实性的活动</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-014" data-v-e5ecfb2d><span class="reading-excerpt-number" aria-hidden="true" data-v-e5ecfb2d>014</span><div data-v-e5ecfb2d><p data-v-e5ecfb2d>过去发生了什么与你的“此时此刻”没有任何关系，未来会如何也不是“此时此刻”要考虑的问题</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-015" data-v-e5ecfb2d><span class="reading-excerpt-number" aria-hidden="true" data-v-e5ecfb2d>015</span><div data-v-e5ecfb2d><p data-v-e5ecfb2d>人生很简单，并不是什么深刻的事情。如果认真过好了每一个刹那，就没有什么必要令其过于深刻</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-016" data-v-e5ecfb2d><span class="reading-excerpt-number" aria-hidden="true" data-v-e5ecfb2d>016</span><div data-v-e5ecfb2d><p data-v-e5ecfb2d>人生中最大的谎言就是不活在“此时此刻”。纠结过去、关注未来，把微弱而模糊的光打向人生整体，自认为看到了些什么</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-017" data-v-e5ecfb2d><span class="reading-excerpt-number" aria-hidden="true" data-v-e5ecfb2d>017</span><div data-v-e5ecfb2d><p data-v-e5ecfb2d>人生的意义是什么？人为了什么而活？当有人提出这个问题的时候，阿德勒的回答是：“并不存在普遍性的人生意义。”</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-018" data-v-e5ecfb2d><span class="reading-excerpt-number" aria-hidden="true" data-v-e5ecfb2d>018</span><div data-v-e5ecfb2d><p data-v-e5ecfb2d>例如战祸或天灾，我们所居住的世界充满了各种不合理的事情。我们也不可能在被卷入战祸而丧命的孩子们面前谈什么“人生意义”。也就是说，人生并不存在可以作为常识来讲的意义。</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-019" data-v-e5ecfb2d><span class="reading-excerpt-number" aria-hidden="true" data-v-e5ecfb2d>019</span><div data-v-e5ecfb2d><p data-v-e5ecfb2d>所以阿德勒在说了“并不存在普遍性的人生意义”之后还说：“人生意义是自己赋予自己的。”</p></div></blockquote><blockquote class="reading-excerpt" id="excerpt-020" data-v-e5ecfb2d><span class="reading-excerpt-number" aria-hidden="true" data-v-e5ecfb2d>020</span><div data-v-e5ecfb2d><p data-v-e5ecfb2d>必须有人开始。即使别人不合作，那也与你无关。我的意见就是这样。应该由你开始，不用去考虑别人是否合作。”</p></div></blockquote><h2 id="文后" tabindex="-1" data-v-e5ecfb2d>文后 <a class="header-anchor" href="#文后" aria-label="Permalink to “文后”" data-v-e5ecfb2d>​</a></h2><blockquote class="reading-excerpt" id="excerpt-021" data-v-e5ecfb2d><span class="reading-excerpt-number" aria-hidden="true" data-v-e5ecfb2d>021</span><div data-v-e5ecfb2d><p data-v-e5ecfb2d>我们这个世界根本不存在什么真正意义上的“过去”。人人都是“我”这个故事的编纂者，为了证明“现在的我”的正统性，其过去往往会被随意改写。人会从过去发生的庞大事件系统中只选择符合现在“目的”的事件并赋予其意义，继而当作自己的记忆。反过来说就是不符合现在“目的”的事件会被抹掉。</p></div></blockquote><footer class="reading-footer" data-v-e5ecfb2d><span data-v-e5ecfb2d>书籍来源：微信读书</span><span data-v-e5ecfb2d>整理时间：2025年</span></footer>',29))])])}const _=c(b,[["render",u],["__scopeId","data-v-e5ecfb2d"]]);export{q as __pageData,_ as default};
